#!/bin/bash
# review sheets from viewer shots (repo root)
P=level_generation/creatures/mm9_banshee_claude; V=level_generation/creatures/claude_shared/gltf_venv/bin/python
for t in a b c; do
 python3 $P/scripts/vshot.py $P/review/sheet_tier_banshee_$t.png 4 --tier banshee_$t ${t}_f:Standing:0.4:0:6:3.6:1.05 ${t}_q:Standing:0.4:35:6:3.6:1.05 ${t}_s:Standing:0.4:90:6:3.6:1.05 ${t}_b:Standing:0.4:180:6:3.6:1.05 2>&1 | tail -1 | cut -c1-60
 $V -W ignore $P/scripts/jshot.py $P/review/sheet_head_banshee_$t.png 4 --tier banshee_$t ${t}_h1:Standing:0:Xhead:0:-3:0.62 ${t}_h2:Standing:0:Xhead:40:0:0.62 ${t}_h3:Standing:0:Xhead:90:0:0.62 ${t}_h4:Standing:0:Xhead:170:5:0.75 ${t}_h5:AttackRanged:0.7:Xjaw:15:-10:0.5 ${t}_h6:AttackMelee:0.7:Xjaw:10:-20:0.5 ${t}_h7:Hit:0.2:Xjaw:40:-10:0.5 ${t}_h8:Taunt:0.35:Xjaw:10:-30:0.55 2>/dev/null | tail -1 | cut -c1-60
done
$V -W ignore $P/scripts/jshot.py $P/review/sheet_closeups_arms.png 4 --tier banshee_a e1:Standing:1.0:Zarm01:-50:5:0.5 e2:Fidget2:1.47:Zarm01:-60:10:0.5 e3:AttackMelee:0.27:Zarm01:-60:10:0.5 e4:Taunt:0.7:Zarm:50:0:0.5 a1:Standing:1.0:Zarmpiv01:-110:-25:0.45 a2:AttackMelee:0.27:Zarmpiv01:-100:-25:0.45 a3:Taunt:0.3:Zarmpiv:100:-25:0.45 a4:AttackRanged:0.6:Zarmpiv:100:-25:0.45 h1:Standing:1.0:Zhand01:-20:30:0.4 h2:AttackMelee:0.3:Zhand:30:10:0.4 h3:Fidget:1.0:Zhand01:-30:0:0.4 h4:Death:0.5:Zhand:40:10:0.45 2>/dev/null | tail -1 | cut -c1-60
$V -W ignore $P/scripts/jshot.py $P/review/sheet_closeups_neck.png 4 --tier banshee_b n1:Standing:0:Xneck:45:-15:0.42 n2:Standing:0:Xneck:130:0:0.45 n3:Hit:0.2:Xneck:40:-20:0.45 n4:Hit2:0.3:Xneck:-40:-20:0.45 n5:AttackMelee:0.5:Xneck:-30:-15:0.5 n6:AttackRanged:0.3:Xneck:30:-20:0.45 n7:Taunt:0.25:Xneck:60:-15:0.45 n8:Death:0.4:Xneck:30:-10:0.5 2>/dev/null | tail -1 | cut -c1-60
$V -W ignore $P/scripts/jshot.py $P/review/sheet_closeups_drape.png 4 --tier banshee_c d1:Standing:0.4:XCENTER:0:0:1.2 d2:Standing:0.4:XCENTER:90:0:1.4 d3:Standing:0.4:XCENTER:180:0:1.4 d4:Standing:0.4:XCENTER:-60:-30:1.4 w1:Walking:0.3:XCENTER:150:15:1.6 w2:Walking:0.5:XCENTER:-30:10:1.6 w3:Fidget2:1.87:XCENTER:200:10:1.6 w4:AttackRanged2:0.22:XCENTER:170:10:1.6 x1:AttackMelee:0.7:Zarm01:150:5:0.7 x2:AttackMelee:0.7:Zarm:-150:5:0.7 x3:Dead:0.5:XCENTER:40:50:1.3 x4:Dead:0.5:XCENTER:-140:35:1.3 2>/dev/null | tail -1 | cut -c1-60
